// seed: tests/seed.free.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - пункт «מה מקבלים» №2 на странице: «3 הצעות עם הסבר למה דווקא הם» (в плане «הן»);
//  - разделитель в цене и в подписи FAQ — «·» (в плане «•»); принимаем оба;
//  - кнопка в шапке называется «סגירה» (в плане «стрелка назад»); заголовок «שדכנית אישית»;
//  - есть дополнительный подзаголовок «שדכנית אמיתית שמכירה אותך ומחפשת בשבילך» / «3 הצעות מותאמות · עד 3 חודשים».
// Только просмотр: «להתחיל — ₪249.90» не нажимается.
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free-r13.json'),
  colorScheme: 'dark',
});

test.describe('שדכנית אישית (#3a3cb9 #58614c)', () => {
  test('Экран услуги: «מה מקבלים», «איך זה עובד», цена, 24 часа, «להתחיל — ₪249.90» @iphone @prod-safe', async ({ page }) => {
    // 1. /settings → «השידוך שלי»
    await page.goto('/settings');
    await page.getByRole('button', { name: 'השידוך שלי' }).click();
    await expect(page).toHaveURL(/\/matchmaker$/);

    // 2. Экран до низа
    await expect(page.getByText('שדכנית אישית', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'סגירה' })).toBeVisible();

    await expect(page.getByText('מה מקבלים', { exact: true })).toBeVisible();
    for (const item of ['שיחת היכרות אישית', /^3 הצעות עם הסבר למה דווקא (הם|הן)$/, 'צ׳אט ישיר עם השדכנית', 'עזרה בתיאום הפגישה']) {
      await expect(page.getByText(item, { exact: typeof item === 'string' })).toBeVisible();
    }

    await expect(page.getByText('איך זה עובד', { exact: true })).toBeVisible();
    const steps = ['ממלאים שאלון קצר (2 דק׳)', 'שיחת היכרות עם השדכנית', 'מקבלים הצעות בצ׳אט', 'שניכם אומרים כן — הצ׳אט נפתח'];
    for (const [i, step] of steps.entries()) {
      await expect(page.getByText(String(i + 1), { exact: true }).first()).toBeVisible();
      await expect(page.getByText(step, { exact: true })).toBeVisible();
    }

    const start = page.getByRole('button', { name: 'להתחיל — ₪249.90' });
    await start.scrollIntoViewIfNeeded();
    await expect(page.getByText(/^החל מ־₪249\.90\s*[·•]\s*תשלום חד־פעמי$/)).toBeVisible();
    await expect(page.getByText('חזרה משוערת מהשדכנית: תוך 24 שעות')).toBeVisible();
    await expect(start).toBeVisible();

    const faq = page.getByRole('button', { name: /^שאלות נפוצות/ });
    await expect(faq).toBeVisible();
    await expect(faq.getByText(/^מה אם לא נמצא\?\s*[·•]\s*מי רואה את השאלון\?$/)).toBeVisible();
  });
});
